  'landing.faq.whatIsQ': 'Mis on Tutlio?',
  'landing.faq.whatIsA': 'Tutlio on tuutorite haldamise platvorm, mis aitab eraõpetajatel ja koolidel hallata ajakava, makseid, suhtlust õpilastega ja tundide ajalugu ühes kohas.',
  'landing.faq.whoForQ': 'Kellele on Tutlio mõeldud?',
  'landing.faq.whoForA': 'Tutlio on mõeldud eraõpetajatele, muusikaõpetajatele, keeleõpetajatele, matemaatikaõpetajatele, tuutorikoolidele ja hariduskeskustele.',
  'landing.faq.waitlistQ': 'Kuidas toimib õpilaste ootenimekiri?',
  'landing.faq.waitlistA': 'Kui õpilane tühistab tunni, pakutakse vabanenud aega automaatselt ootenimekirjas olevatele õpilastele. Kes esimesena kinnitab, saab koha — nii ei kaota õpetaja tulu.',
  'landing.faq.freeTrialQ': 'Kas on tasuta prooviperiood?',
  'landing.faq.freeTrialA': 'Jah! Kõik uued kontod saavad automaatselt 7 päeva tasuta – koodi pole vaja. Prooviperioodil tasu ei võeta ja saate igal ajal tühistada.',
  'landing.faq.languagesQ': 'Millistes keeltes on Tutlio saadaval?',
  'landing.faq.languagesA': 'Tutlio on saadaval 12 keeles: leedu, inglise, poola, läti, eesti, prantsuse, hispaania, saksa, rootsi, taani, soome ja norra.',
  'landing.faqTitle': 'Korduma kippuvad küsimused',
  'feature.calendar.pageTitle': 'Nutikas tuutorite kalender ja ajakava tarkvara',
  'feature.calendar.pageDesc': 'Laske õpilastel ise tunde broneerida teie saadaolevatest aegadest. Tutlio nutikas kalender haldab automaatselt korduvaid tunde, pause ja broneeringu tähtaegu.',
  'feature.calendar.detailsTitle': 'Kuidas nutikas kalender töötab',
  'feature.calendar.selfBooking': 'Õpilaste iseteeninduslik broneerimine',
