  'feature.calendar.recurring': 'Korduvad tunnid',
  'feature.calendar.recurringDesc': 'Looge iganädalasi või kahenädalasi korduvaid tunde, mis ilmuvad automaatselt mõlema kalendrisse.',
  'feature.calendar.breaks': 'Pauside haldamine',
  'feature.calendar.breaksDesc': 'Seadistage automaatsed pausid tundide vahel.',
  'feature.calendar.deadlines': 'Broneeringu tähtajad',
  'feature.calendar.deadlinesDesc': 'Määrake, kui palju ette peavad õpilased broneerima (nt 24 tundi ette).',
  'feature.calendar.faq.howBookQ': 'Kuidas õpilased tunde broneerivad?',
  'feature.calendar.faq.howBookA': 'Õpilased saavad isikliku broneeringulingi, kus nad näevad teie saadaolevaid aegu ja saavad otse broneerida.',
  'feature.calendar.faq.groupLessonsQ': 'Kas saan planeerida grupitunde?',
  'feature.calendar.faq.groupLessonsA': 'Jah! Saate luua grupitunni aegu, kuhu mitu õpilast saavad registreeruda.',
  'feature.calendar.faq.mobileCalendarQ': 'Kas kalender töötab telefonis?',
  'feature.calendar.faq.mobileCalendarA': 'Jah, Tutlio töötab igas seadmes — arvutis, tahvelarvutis või telefonis.',
  'feature.waitlist.pageTitle': 'Õpilaste ootenimekiri — ärge kaotage tulu tühistamiste tõttu',
  'feature.waitlist.pageDesc': 'Kui õpilane tühistab, pakub Tutlio automaatselt vabanenud aja ootenimekirja õpilastele.',
  'feature.waitlist.detailsTitle': 'Kuidas ootenimekiri töötab',
  'feature.waitlist.autoFill': 'Automaatne kohtade täitmine',
  'feature.waitlist.autoFillDesc': 'Kui tund tühistatakse, teavitab süsteem kohe ootenimekirjas olevaid õpilasi.',
  'feature.waitlist.notifications': 'Kohesed teavitused',
  'feature.waitlist.notificationsDesc': 'Ootenimekirjas olevad õpilased saavad kohese e-posti teavituse, kui nende eelistatud aeg vabaneb.',
  'feature.waitlist.priority': 'Prioriteedijärjekord',
  'feature.waitlist.priorityDesc': 'Õpilased liituvad ootenimekirjaga konkreetsetele aegadele. Järjekord tagab õiglase juurdepääsu.',
  'feature.waitlist.revenue': 'Tulu kaitse',
  'feature.waitlist.revenueDesc': 'Lõpetage tulu kaotamine tühistamiste tõttu. Ootenimekiri tagab kohtade kiire täitmise.',
  'feature.waitlist.faq.howWorksQ': 'Kuidas ootenimekiri täidab tühistatud kohad?',
  'feature.waitlist.faq.howWorksA': 'Kui õpilane tühistab, kontrollib süsteem ootenimekirja ja saadab pakkumise. Esimene kinnitanud õpilane saab tunni.',
  'feature.waitlist.faq.studentLimitQ': 'Kas ootenimekirjas on õpilaste piirang?',
  'feature.waitlist.faq.studentLimitA': 'Ei, piirangut pole. Suvaline arv õpilasi saab ootenimekirjaga liituda.',
  'feature.waitlist.faq.automaticQ': 'Kas protsess on täielikult automaatne?',
  'feature.waitlist.faq.automaticA': 'Jah! Pärast seadistamist on kogu voog — tühistamisest uuesti broneerimiseni — täielikult automatiseeritud.',
  'feature.payments.pageTitle': 'Tuutori maksete töötlemine ja arveldamine',
  'feature.payments.pageDesc': 'Võtke vastu õpilaste makseid Stripe kaudu, jälgige kes on maksnud, genereerige arveid ja vaadake igakuiseid tulude kokkuvõtteid.',
  'feature.payments.detailsTitle': 'Maksefunktsioonid',
  'feature.payments.stripe': 'Stripe integratsioon',
  'feature.payments.stripeDesc': 'Võtke vastu krediit- ja deebetkaardimakseid turvaliselt Stripe kaudu sisseehitatud 3D Secure kaitsega.',
  'feature.payments.tracking': 'Maksete jälgimine',
  'feature.payments.trackingDesc': 'Vaadake kohe, millised õpilased on maksnud, millised maksed ootavad ja millised on hilinenud.',
  'feature.payments.invoices': 'Arvete genereerimine',
  'feature.payments.invoicesDesc': 'Genereerige professionaalseid arveid õpilastele või vanematele ja saatke need otse e-postiga.',
  'feature.payments.packages': 'Tunnipaketid',
  'feature.payments.packagesDesc': 'Müüge tunnipakette (nt 10 tundi soodushinnaga) ja jälgige kasutust automaatselt.',
  'feature.payments.faq.methodsQ': 'Milliseid maksemeetodeid toetatakse?',
  'feature.payments.faq.methodsA': 'Tutlio kasutab Stripe\'i, mis toetab kõiki peamisi krediit- ja deebetkaarte, Apple Pay\'d, Google Pay\'d ja pangaülekandeid.',
  'feature.payments.faq.feesQ': 'Kas Tutlio võtab maksete eest lisatasusid?',
  'feature.payments.faq.feesA': 'Tutlio ei võta lisatasusid peale tellimuse. Kehtivad Stripe standardsed töötlustasud.',
  'feature.payments.faq.invoiceAutoQ': 'Kas arveid saab automaatselt genereerida?',
  'feature.payments.faq.invoiceAutoA': 'Jah, saate genereerida arveid iga õpilase või perioodi kohta ja saata need otse platvormilt.',
  'feature.reminders.pageTitle': 'Automaatsed tunni meeldetuletused õpetajatele',
  'feature.reminders.pageDesc': 'Saatke automaatseid e-posti meeldetuletusi enne tunde, tagasisidet pärast tunde ja hilinenud maksete teavitusi.',
