  'feature.reminders.afterLesson': 'Tagasiside pärast tundi',
  'feature.reminders.afterLessonDesc': 'Saatke automaatseid e-kirju pärast tunde märkmete, kodutööde või juhistega.',
  'feature.reminders.paymentDue': 'Makse meeldetuletused',
  'feature.reminders.paymentDueDesc': 'Automaatsed teavitused hilinenud maksete kohta.',
  'feature.reminders.customTiming': 'Kohandatav ajastus',
  'feature.reminders.customTimingDesc': 'Seadistage täpselt, millal iga meeldetuletuse tüüp saadetakse.',
  'feature.reminders.faq.channelsQ': 'Kuidas meeldetuletusi saadetakse?',
  'feature.reminders.faq.channelsA': 'Meeldetuletused saadetakse e-postiga. Õpilased saavad neid automaatselt vastavalt teie seadistatud ajakavale.',
  'feature.reminders.faq.customizeQ': 'Kas saan meeldetuletuse sõnumeid kohandada?',
  'feature.reminders.faq.customizeA': 'Süsteem saadab professionaalseid, lokaliseeritud meeldetuletusi õpilase keeles.',
  'feature.reminders.faq.disableQ': 'Kas õpilased saavad meeldetuletustest loobuda?',
  'feature.reminders.faq.disableA': 'Tunni meeldetuletused on kogemuse oluline osa, kuid õpilased saavad hallata oma teavituste eelistusi oma profiilis.',

