  'stuSess.refundSuccessStripeNote': '<p class="text-emerald-900 text-sm mb-2">Küsimused või probleemid? Pöörduge <a href="mailto:info@tutlio.lt" class="underline font-medium">info@tutlio.lt</a>.</p><p class="font-semibold text-emerald-900">Teie tagasimakse on Stripe kaudu algatatud.</p><p class="text-emerald-800 mt-1">Kaardi tagasimaksed jõuavad tavaliselt kohale umbes <strong>5–10 tööpäeva</strong> jooksul (pangad võivad varieeruda). Kui te ei saa seda tavapärase aja jooksul, kirjutage <a href="mailto:info@tutlio.lt" class="text-emerald-900 underline font-medium">info@tutlio.lt</a>.</p>',
