  'orgTutorPolicy.title': 'Sisemised reeglid õpetajatele',
  'orgTutorPolicy.intro': 'Enne platvormi kasutamist tutvuge palun organisatsiooni sisemiste reeglitega.',
  'orgTutorPolicy.acceptBtn': 'Sain aru',
  'orgTutorPolicy.viewBtn': 'Vaata sisemisi reegleid',
  'orgTutorPolicy.s1Title': '1. Üldsätted',
  'orgTutorPolicy.s1Body': 'Need reeglid reguleerivad teie kui õpetaja või tuutori ("Õpetaja") Tutlio platvormi ("Platvorm") kasutamist. Teid on kutsutud Platvormi kasutama haridusagentuuri, kooli või tuutorluskeskuse poolt, mida te esindate ("Organisatsioon"). Platvormi tehnilist tuge ja hooldust tagab MB Tutlio. Oma kontot kasutades nõustute nende Reeglite ja Privaatsuspoliitikaga.',
  'orgTutorPolicy.s2Title': '2. Konto haldamine ja tunniplaan',
  'orgTutorPolicy.s2Intro': 'Platvorm on loodud nii, et te ei peaks raiskama aega tundide aegade kooskõlastamisele õpilastega.',
  'orgTutorPolicy.s2Link': 'Unikaalne link: Teile määratakse isiklik tundide broneerimise link (vastavalt ainete järgi, mida õpetate), mida õpilased kasutavad tundide kokkuleppimiseks.',
  'orgTutorPolicy.s2Calendar': 'Kalendri sünkroonimine: Teie saadavus sõltub otseselt Google Calendar integratsioonist (kahesuunaline sünkroonimine). Te olete isiklikult vastutav selle eest, et teie kalendris näidatud vaba aeg oleks õige ja ajakohane. Platvorm ei luba õpilastel broneerida aegu, mis on teie kalendris märgitud hõivatuna.',
  'orgTutorPolicy.s2Security': 'Konto turvalisus: Teie konto on isiklik. Te peate hoidma oma sisselogimisandmed turvaliselt ega tohi neid kolmandatele isikutele edastada.',
  'orgTutorPolicy.s3Title': '3. Tundide tühistamine ja ootenimekiri',
  'orgTutorPolicy.s3Intro': 'Platvorm aitab teie tunniplaani maksimaalselt täita ja vältida tühje aknaid:',
  'orgTutorPolicy.s3Auto': 'Kui õpilane tühistab tunni, saadab Platvorm automaatselt teate (SMS/e-post) teistele teie ootenimekirjas olevatele õpilastele, pakkudes vabanenud aega. Teilt ei nõuta mingeid lisatoiminguid.',
  'orgTutorPolicy.s3Rules': 'Tundide tühistamise reeglid (kui palju aega ette saab tühistada, tagajärjed) kehtestab teie Organisatsioon.',
  'orgTutorPolicy.s4Title': '4. Finantsid ja arveldused',
  'orgTutorPolicy.s4Intro': 'Te ei pea muretsema arvete esitamise ega vanematelt maksete kogumise pärast:',
  'orgTutorPolicy.s4Advance': 'Kõik õpilaste (või vanemate) maksed teie tundide eest kogutakse ettemaksuna Platvormi kaudu ja kantakse otse teie Organisatsioonile.',
  'orgTutorPolicy.s4Confirmed': 'Te annate tundi alles siis, kui see on süsteemis kinnitatud (st tasu on juba maha arvestatud).',
  'orgTutorPolicy.s4Contact': 'Palga, väljamaksete ajakava ja muude finantsküsimuste osas pöörduge otse oma Organisatsiooni administraatori poole. MB Tutlio ei teosta Õpetajatega mingeid otseseid finantstehinguid.',
  'orgTutorPolicy.s5Title': '5. Õpilaste andmekaitse (GDPR)',
  'orgTutorPolicy.s5Intro': 'Õpetajana on teil juurdepääs õpilaste isikuandmetele, sisemistele märkmetele ja õppematerjalidele. Te kohustute:',
  'orgTutorPolicy.s5Use': 'Kasutama neid andmeid üksnes tundide korraldamiseks ja läbiviimiseks.',
  'orgTutorPolicy.s5NoCopy': 'Mitte kopeerima, eksportima ega levitama õpilaste või vanemate kontaktandmeid väljaspool Platvormi.',
  'orgTutorPolicy.s5Notes': 'Kaitsma Organisatsiooni sisemisi andmeid (märkmeid õpilase edasijõudmise kohta), mis on nähtavad ainult teile ja Organisatsiooni juhtkonnale, mitte õpilastele ega vanematele.',
  'orgTutorPolicy.s5Termination': 'Pärast töösuhte lõppemist Organisatsiooniga tühistatakse teie juurdepääs nendele andmetele viivitamatult.',
  'orgTutorPolicy.s6Title': '6. Tehniline toimimine ja vastutuse piiramine',
  'orgTutorPolicy.s6Body': 'Platvormi kasutamine ebaseaduslikel eesmärkidel, ründelinkide levitamine õppematerjalides või muul viisil süsteemi häirimine on keelatud. MB Tutlio tagab Platvormi toimimise ja tehnilise hoolduse, kuid ei vastuta häirete eest, mis on põhjustatud teie internetiühenduse, seadmete rikete või valesti seadistatud Google Calendar seadistuste tõttu.',
  'orgTutorPolicy.s7Title': '7. Tugi ja kontaktid',
  'orgTutorPolicy.s7Org': 'Tunnplaani, palga, õpilaste määramise või töökorralduse küsimustes pöörduge oma Organisatsiooni administraatori poole.',
  'orgTutorPolicy.s7Tech': 'Platvormi tehniliste vigade korral (kalendri sünkroonimine ei tööta, te ei saa teateid) teavitage Organisatsiooni administraatorit, kes võtab ühendust Tutlio tehnilise toe meeskonnaga.',

  'register.orgPolicyConsent': 'Platvormi kasutades nõustute',
  'register.orgPolicyLink': 'sisemiste reeglitega',

