  'feature.cancellation.pageTitle': 'Tühistamisreeglid ja hilise tühistamise tasud õpetajatele',
  'feature.cancellation.pageDesc': 'Määrake selged tühistamistähtajad ja automaatsed hilise tühistamise tasud. Kui õpilased tühistavad, lähevad vabanenud ajad otse teie ootejärjekorda.',
  'feature.cancellation.detailsTitle': 'Kuidas tühistamisreeglid toimivad',
  'feature.cancellation.deadlines': 'Tühistamistähtajad',
  'feature.cancellation.deadlinesDesc': 'Määrake, kui palju ette peavad õpilased tühistama (nt 24 tundi enne tundi), et vältida tühistamistasu.',
  'feature.cancellation.fees': 'Automaatsed hilise tühistamise tasud',
  'feature.cancellation.feesDesc': 'Määrake protsendipõhine tasu (nt 50% tunni hinnast), mida rakendatakse automaatselt, kui õpilane tühistab liiga hilja.',
  'feature.cancellation.transparency': 'Selge suhtlus õpilastega',
  'feature.cancellation.transparencyDesc': 'Õpilased näevad teie tühistamispoliitikat broneerimisel kohe. Üllatusi pole — vaid professionaalsed, õiglased reeglid.',
  'feature.cancellation.waitlistLink': 'Ootejärjekorra integratsioon',
  'feature.cancellation.waitlistLinkDesc': 'Tühistatud ajad pakutakse kohe ootejärjekorras olevatele õpilastele, nii et teie ajakava püsib täis ja tulu on kaitstud.',
  'feature.cancellation.faq.howSetQ': 'Kuidas seada tühistamisreegleid?',
  'feature.cancellation.faq.howSetA': 'Minge oma tunni seadetesse ja määrake tühistamistähtaeg (tunde enne tundi) ja hilise tühistamise tasu protsent. Süsteem rakendab neid automaatselt.',
  'feature.cancellation.faq.refundQ': 'Mis juhtub tühistamistasuga?',
  'feature.cancellation.faq.refundA': 'Hilise tühistamise tasud arvutatakse automaatselt ja lisatakse õpilase saldole. Kõiki tasusid saate jälgida oma finantspaneelis.',
  'feature.cancellation.faq.studentSeeQ': 'Kas õpilased näevad tühistamispoliitikat?',
  'feature.cancellation.faq.studentSeeA': 'Jah, teie tühistamistingimused kuvatakse õpilastele broneerimise käigus, et nad teaksid reegleid enne kinnitamist.',
  'feature.comments.pageTitle': 'Tunnimärkmed, kommentaarid ja failide jagamine õpetajatele',
  'feature.comments.pageDesc': 'Lisage märkmeid, koduülesandeid ja faile üksikutele tundidele. Looge täielik tundide ajalugu, millele õpilased ja vanemad pääsevad igal ajal.',
  'feature.comments.detailsTitle': 'Kuidas tunnimärkmed toimivad',
  'feature.comments.lessonNotes': 'Märkmed iga tunni kohta',
  'feature.comments.lessonNotesDesc': 'Lisage privaatseid või jagatud märkmeid igale tunnile — jälgige, mida käsitleti, õpilase edusamme ja järgmisi samme.',
  'feature.comments.fileSharing': 'Failimanused',
  'feature.comments.fileSharingDesc': 'Laadige üles töölehed, koduülesannete PDF-id või õppematerjalid ja lisage need otse tunnile lihtsaks juurdepääsuks.',
  'feature.comments.history': 'Täielik tundide ajalugu',
  'feature.comments.historyDesc': 'Iga märge ja fail on seotud tunniga, kuhu see kuulub, luues otsitava ajajoone iga õpilase õpiteekonnast.',
  'feature.comments.parentAccess': 'Nähtavus vanematele',
  'feature.comments.parentAccessDesc': 'Vanemad näevad oma portaalis jagatud tunnimärkmeid ja faile, hoides end kursis lapse edusammudega.',
  'feature.comments.faq.whoSeesQ': 'Kes näeb tunnimärkmeid?',
  'feature.comments.faq.whoSeesA': 'Teie valite, mida jagada. Märkmed võivad olla privaatsed (ainult õpetajale) või jagatud õpilase ja tema vanemaga.',
  'feature.comments.faq.fileTypesQ': 'Milliseid failitüüpe saan üles laadida?',
  'feature.comments.faq.fileTypesA': 'Saate üles laadida PDF-e, pilte ja levinud dokumendivorminguid. Failid salvestatakse turvaliselt ja on kättesaadavad igast seadmest.',
  'feature.comments.faq.storageQ': 'Kas on salvestusruumi piirang?',
  'feature.comments.faq.storageA': 'Kõik paketid sisaldavad heldet failimahtu. Failipõhiseid piiranguid pole — lisage nii palju materjale, kui vajate.',
  'noShow.title': 'Õpilane ei tulnud',
